import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static final int MAX_SIZE = 7100;
    static final long INF = 1000000000L;

    static class Edge {
        int from, to;
        long flow, capacity;

        Edge(int from, int to, long flow, long capacity) {
            this.from = from;
            this.to = to;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static class MaxFlow {
        int start, end_point;
        List<Edge> edges = new ArrayList<>();
        List<Integer>[] graph = new ArrayList[MAX_SIZE];
        int[] distance = new int[MAX_SIZE];
        int[] visited = new int[MAX_SIZE];
        int[] current = new int[MAX_SIZE];

        @SuppressWarnings("unchecked")
        MaxFlow() {
            for (int i = 0; i < MAX_SIZE; i++) {
                graph[i] = new ArrayList<>();
            }
        }

        void initialize() {
            edges.clear();
            for (int i = 0; i < MAX_SIZE; i++) {
                graph[i].clear();
            }
        }

        void add_edge(int from, int to, long cap) {
            Edge e1 = new Edge(from, to, 0L, cap);
            Edge e2 = new Edge(to, from, 0L, 0L);
            edges.add(e1);
            edges.add(e2);
            int idx = edges.size() - 2;
            graph[from].add(idx);
            graph[to].add(idx + 1);
        }

        boolean build_level_graph() {
            Arrays.fill(visited, 0);
            Arrays.fill(distance, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(start);
            visited[start] = 1;
            distance[start] = 0;
            while (!q.isEmpty()) {
                int v = q.poll();
                for (int i : graph[v]) {
                    Edge e = edges.get(i);
                    int nxt = e.to;
                    if (visited[nxt] == 0 && e.capacity > e.flow) {
                        distance[nxt] = distance[v] + 1;
                        q.offer(nxt);
                        visited[nxt] = 1;
                    }
                }
            }
            return visited[end_point] == 1;
        }

        long send_flow(int v, long flow) {
            if (v == end_point || flow == 0) return flow;
            long total_flow = 0;
            for (int i = current[v]; i < graph[v].size(); i++) {
                int idx = graph[v].get(i);
                Edge e = edges.get(idx);
                if (distance[v] + 1 == distance[e.to]) {
                    long min_cap = Math.min(flow, e.capacity - e.flow);
                    long pushed = send_flow(e.to, min_cap);
                    if (pushed > 0) {
                        e.flow += pushed;
                        edges.get(idx ^ 1).flow -= pushed;
                        total_flow += pushed;
                        flow -= pushed;
                        if (flow == 0) break;
                    }
                }
                current[v]++;
            }
            return total_flow;
        }

        long max_flow() {
            long total = 0;
            while (build_level_graph()) {
                Arrays.fill(current, 0);
                total += send_flow(start, INF);
            }
            return total;
        }
    }

    static char[][] grid1 = new char[14][14];
    static char[][] grid2 = new char[14][14];
    static boolean[][] visited_cells = new boolean[14][14];
    static int[][] dist_cells = new int[14][14];
    static int n;
    static int[] target = new int[103];

    static void BFS(int x, int y, int n, char[][] grid1, boolean[][] visited_cells, int[][] dist_cells) {
        for (int i = 0; i < 14; i++) {
            Arrays.fill(dist_cells[i], 111);
        }
        for (int i = 0; i < 14; i++) {
            Arrays.fill(visited_cells[i], false);
        }
        Queue<int[]> q = new LinkedList<>();
        dist_cells[x][y] = 0;
        q.offer(new int[]{x, y});
        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int cx = p[0], cy = p[1], d = dist_cells[cx][cy];
            if (visited_cells[cx][cy]) continue;
            visited_cells[cx][cy] = true;
            dist_cells[cx][cy] = d;
            for (int i = 0; i < 4; i++) {
                int tx = cx + dx[i], ty = cy + dy[i];
                if (tx <= 0 || tx > n || ty <= 0 || ty > n || visited_cells[tx][ty] || grid1[tx][ty] == 'Y') continue;
                q.offer(new int[]{tx, ty});
                dist_cells[tx][ty] = d + 1;
            }
        }
    }

    static int get_index(int level, int x, int y, int n) {
        return level * n * n + (x - 1) * n + y;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid1[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                grid2[i][j] = line.charAt(j - 1);
            }
        }

        MaxFlow mf = new MaxFlow();
        mf.start = 0;
        mf.end_point = MAX_SIZE - 2;

        int x = 0, y = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] == 'Z') {
                    x = i;
                    y = j;
                    break;
                }
            }
        }

        for (int i = 1; i <= n * n; i++) {
            target[i] = MAX_SIZE - 3 - (n * n - i);
        }

        BFS(x, y, n, grid1, visited_cells, dist_cells);

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (grid1[i][j] >= '0' && grid1[i][j] <= '9') {
                    mf.add_edge(mf.start, get_index(0, i, j, n), grid1[i][j] - '0');
                }
                if (grid2[i][j] >= '0' && grid2[i][j] <= '9') {
                    mf.add_edge(target[get_index(0, i, j, n)], mf.end_point, grid2[i][j] - '0');
                }
                mf.add_edge(get_index(0, i, j, n), target[get_index(0, i, j, n)], INF);
            }
        }

        int[] dx = {1, 0, 0, -1};
        int[] dy = {0, 1, -1, 0};

        for (int i = 1; i <= t; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= n; k++) {
                    if (grid1[j][k] == 'Y' || grid1[j][k] == 'Z') continue;
                    for (int l = 0; l < 4; l++) {
                        int tx = j + dx[l], ty = k + dy[l];
                        if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && grid1[tx][ty] != 'Y' && grid1[tx][ty] != 'Z') {
                            if (dist_cells[j][k] >= i && dist_cells[tx][ty] >= i) {
                                mf.add_edge(get_index(i - 1, tx, ty, n), get_index(i, j, k, n), INF);
                            }
                        }
                    }
                    mf.add_edge(get_index(i, j, k, n), target[get_index(0, j, k, n)], INF);
                }
            }
        }

        System.out.println(mf.max_flow());
    }
}

